mapper.select:
SELECT warehouse_id, code, max(name) as name FROM warehouse_location WHERE is_deleted = false and type = 'location' and warehouse_id IN
#{item}
group by warehouse_id,code

SELECT wl.id as warehouseLocationId, wt.id as warehouseId, wt.name as warehouseName, wt.disabled, wt.org_id AS orgId, wt.kingdee_warehouse_code AS warehouseCode, wt.type_id AS typeId, db."name" AS warehouseType, wl.code as warehouseLocation, wl."name" as warehouseLocationName, wa.code as warehouseArea, wa."name" as warehouseAreaName FROM "warehouse_location" wl LEFT JOIN warehouse wt on wl.warehouse_id = wt.id LEFT JOIN "warehouse_location" wa on wl.parent_id = wa.id LEFT JOIN "dict_basic" db on db.id = wt.type_id and db.is_deleted = false and db.type = 'warehouseType' where wl.is_deleted = false and wl."type" = 'location' and wt.disabled = false and wl.disabled = false and wa.disabled = false and wt.approve_status = 'approve'
AND wt.type_id IN
#{typeId}
AND wt.org_id IN
#{item}
AND wl.warehouse_id IN
#{item}
AND wa.id IN
#{item}
AND wl.code ilike concat('%', #{params.warehouseLocation}::text ,'%')
ORDER BY warehouseName,warehouseArea,warehouseLocation desc

select id,code,name,status,disabled from ( select wl.id, wl.code, wl.name, wl.status, wl.disabled from warehouse_location wl left join warehouse_location wa on wl.parent_id = wa.id where wl.is_deleted = false and wl.type = 'location'
and wl.warehouse_id = #{params.warehouseId}
and ((wl.code = #{params.searchKeyword}) or wl.name ilike concat('%', #{params.searchKeyword}::text ,'%'))
and wl.parent_id = #{params.warehouseAreaId}
and wa.area_type = #{params.areaType}
order by
case when wl.name ILIKE concat(#{params.searchKeyword}::text,'%') THEN 1 when wl.name ILIKE concat('%',#{params.searchKeyword}::text) THEN 2 when wl.name ILIKE concat('%',#{params.searchKeyword}::text,'%') THEN 3 end , wl.name,
wl.code asc ) wls

SELECT wl.id, wl.code, wl.name, wl.area_type, wl.warehouse_id, wl.disabled, wl.status, wl.remark, wl.update_user_name, wl.update_time FROM warehouse_location AS wl where ${params.sqlMap.default}
${params.permissionSql}
and wl.type = 'area' and is_deleted = false order by wl.create_time desc,wl.id desc

select wl.id, wl.code, wl.name, wa.area_type as areaType, wl.status, wl.disabled, wl.remark, wl.update_user_name as updateUserName, wl.update_time as updateTime, wa.id as warehouseAreaId, wa.code as warehouseAreaCode, wa.name as warehouseAreaName, wt.id as warehouseId, wt.kingdee_warehouse_code as warehouseCode, wt.name as warehouseName from warehouse_location wl INNER join warehouse_location wa on wl.parent_id = wa.id AND wa.is_deleted = FALSE inner join warehouse wt on wl.warehouse_id = wt.id where wl.is_deleted = false and wt.is_deleted = false and wt.approve_status = 'approve' and ${params.sqlMap.default}
${params.permissionSql}
${item.field} ${item.sort}
order by wl.create_time desc

SELECT wl.id as id, wl.code as code, wl.name as name, wl.warehouse_id as warehouseId, wt.kingdee_warehouse_code warehouseCode, wt.name as warehouseName, wa.id as warehouseAreaId, wa.code as warehouseAreaCode, wa.name as warehouseAreaName, wl.status, wl.disabled, wl.remark, wl.update_user_name as updateUserName, wl.update_time as updateTime FROM warehouse_location wl -- LEFT JOIN warehouse wt on wl.warehouse_id = wt.id LEFT JOIN warehouse_location wa on wl.parent_id = wa.id -- LEFT JOIN dict_basic db on db.id = wt.type_id and db.is_deleted = false and db.type = 'warehouseType' where wl.is_deleted = false and wl.type = 'location' and wa.is_deleted = false and wa.disabled = false -- and wt.is_deleted = false and wt.disabled = false and wt.approve_status = 'approve'
${params.permissionSql}
${item.field} ${item.sort}
order by wl.create_time desc

select T.id, T.code, T.name, S.code warehouseAreaCode, M.kingdee_warehouse_code warehouseCode, T.status, T.disabled, T.remark, T.update_user_name, T.update_time from warehouse_location T inner join warehouse_location S on T.parent_id = S.id left join warehouse M on S.parent_id = M.id where T.is_deleted = false and T.disabled = false and S.is_deleted = false and S.disabled = false and M.is_deleted = false and M.disabled = false
and T.id in
#{id}

select T.id,
       T.code,
       T.name,
       S.code                   warehouseAreaCode,
       M.kingdee_warehouse_code warehouseCode,
       T.status,
       T.disabled,
       T.remark,
       T.update_user_name,
       T.update_time
from warehouse_location T
         inner join warehouse_location S on T.parent_id = S.id
         left join warehouse M on S.parent_id = M.id
where T.is_deleted = false and T.disabled = false
  and S.is_deleted = false and S.disabled = false
  and M.is_deleted = false and M.disabled = false

    and T.code = #{dto.code}


    and M.kingdee_warehouse_code = #{dto.warehouseCode}


    and S.code = #{dto.warehouseCode}


    and T.status = #{dto.status}


    and T.disabled = #{dto.disabled}


    and T.update_user_name = #{dto.updateUserName}


    and T.update_time between #{dto.updateTimeList[0]} and #{dto.updateTimeList[1]}

select wl.id, wl.code, wl.name, (case when wl.status = 'idle' then '可分配' when wl.status = 'recyclable' then '可回收' when wl.status = 'occupied' then '被占用' ELSE '' end) status, (case when wl.disabled = true then '禁用' when wl.disabled = false then '启用' else '' end) disabled, wl.remark, wl.update_user_name as updateUserName, wl.update_time as updateTime, wa.name as warehouseAreaName, wt.name as warehouseName from warehouse_location wl inner join warehouse_location wa on wl.parent_id = wa.id inner join warehouse wt on wl.warehouse_id = wt.id where wl.is_deleted = false and wa.is_deleted = false and wt.is_deleted = false and wa.disabled = false and wt.disabled = false and wt.approve_status = 'approve' and ${dto.sqlMap.default}
${dto.permissionSql}
order by wl.create_time desc

select wa.* from warehouse_location wl left join warehouse_location wa on wl.parent_id = wa.id
where wa.is_deleted = false and wl.is_deleted = false
and wl.warehouse_id = #{warehouseId} and wl.code = #{warehouseLocation}

SELECT DISTINCT wl.ID, wl.warehouse_id, wl.code AS warehouseCode, wl.NAME AS warehouseName, wa.code as warehouseLocationCode, wa.name as warehouseLocationName, i.qty, i.sku_id, i.sku_no FROM warehouse_location AS wl INNER JOIN inventory AS i ON wl.warehouse_id = i.warehouse_id AND i.is_deleted =FALSE INNER join warehouse_location as wa on wa.parent_id = wl.id and i.warehouse_location = wa.code and wa.is_deleted =FALSE WHERE wl.is_deleted = FALSE AND wl.area_type != 'pickingArea' AND i.qty > 0 AND i.dict_inventory_status = 'usable'
AND i.sku_no = #{skuNo}
AND wl.warehouse_id = #{warehouseId}
ORDER BY i.qty DESC limit 1
